      cylinder:`<path d="M19 26v49c0 10 62 10 62 0V26Z" fill="${color}" stroke="#514b9c" stroke-width="3"/><ellipse cx="50" cy="26" rx="31" ry="12" fill="#b7c3ff" stroke="#514b9c" stroke-width="3"/><path d="M19 75c0 10 62 10 62 0" fill="none" stroke="#514b9c" stroke-width="3"/>`
